package main

import (
	"fmt"
	"time"
)

func main() {
	fmt.Println("=== 1. For (Sama seperti While) ===")
	tries := 1
	for tries <= 3 {
		fmt.Printf("Mencoba koneksi... ke-%d\n", tries)
		tries++
	}

	fmt.Println("\n=== 2. For Range (Sangat Idiomatik) ===")
	// Mengiterasi sebuah slice dari string
	servers := []string{"api-server-1", "database-node", "cache-redis"}

	// range mengembalikan index dan nilai (value)
	for i, server := range servers {
		fmt.Printf("Node %d: %s\n", i, server)
	}

	fmt.Println("\n=== 3. Mengabaikan Index dengan Blank Identifier (_) ===")
	// Jika kita tidak butuh index, gunakan underscore (_)
	// Go akan menolak compile jika kita mendeklarasikan index tapi tidak memakainya.
	for _, server := range servers {
		fmt.Println("Checking health for:", server)
	}
}
